package dev.industrialtechnology.client;
import java.io.*;import java.util.*;import org.lwjgl.opengl.GL11;import net.minecraft.client.Minecraft;import net.minecraft.util.ResourceLocation;
/** Small legacy OBJ renderer. Geometry is compiled once into display lists; no per-frame mesh allocation. */
public final class RailMesh {
 private static final Map<String,Integer> lists=new HashMap<>();public static final ResourceLocation MATERIALS=new ResourceLocation("industrialtech:textures/entity/rail_materials.png");
 public static void clear(){for(int id:lists.values())GL11.glDeleteLists(id,1);lists.clear();}
 public static void draw(String name){Integer id=lists.get(name);if(id==null){id=load(name);lists.put(name,id);}GL11.glCallList(id);}
 private static int load(String name){int id=GL11.glGenLists(1);List<double[]> vertices=new ArrayList<>(),uv=new ArrayList<>();List<String[]> faces=new ArrayList<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(Minecraft.getMinecraft().getResourceManager().getResource(new ResourceLocation("industrialtech:models/railway/"+name+".obj")).getInputStream(),"UTF-8"))){String line;while((line=r.readLine())!=null){String[] a=line.trim().split("\\s+");if(a[0].equals("v"))vertices.add(new double[]{Double.parseDouble(a[1]),Double.parseDouble(a[2]),Double.parseDouble(a[3])});else if(a[0].equals("vt"))uv.add(new double[]{Double.parseDouble(a[1]),Double.parseDouble(a[2])});else if(a[0].equals("f"))faces.add(Arrays.copyOfRange(a,1,a.length));}}catch(IOException e){throw new IllegalStateException("Missing railway mesh "+name,e);}GL11.glNewList(id,GL11.GL_COMPILE);GL11.glBegin(GL11.GL_TRIANGLES);for(String[] f:faces)for(int i=1;i<f.length-1;i++){String[] tri={f[0],f[i],f[i+1]};double[][] p=new double[3][],t=new double[3][];for(int j=0;j<3;j++){String[] idx=tri[j].split("/");p[j]=vertices.get(Integer.parseInt(idx[0])-1);t[j]=uv.get(Integer.parseInt(idx[1])-1);}double ax=p[1][0]-p[0][0],ay=p[1][1]-p[0][1],az=p[1][2]-p[0][2],bx=p[2][0]-p[0][0],by=p[2][1]-p[0][1],bz=p[2][2]-p[0][2];double nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx,len=Math.sqrt(nx*nx+ny*ny+nz*nz);if(len<1e-9)continue;GL11.glNormal3d(nx/len,ny/len,nz/len);for(int j=0;j<3;j++){GL11.glTexCoord2d(t[j][0],1-t[j][1]);GL11.glVertex3d(p[j][0],p[j][1],p[j][2]);}}GL11.glEnd();GL11.glEndList();return id;}
 public static void box(double x,double y,double z,double w,double h,double l,int mat){double u=(mat%4)/4.0+.01,v=(mat/4)/4.0+.01,U=u+.23,V=v+.23;double a=x-w/2,b=x+w/2,c=z-l/2,d=z+l/2;double[][][] faces={{{a,y,c},{a,y+h,c},{b,y+h,c},{b,y,c}},{{b,y,d},{b,y+h,d},{a,y+h,d},{a,y,d}},{{a,y,d},{a,y+h,d},{a,y+h,c},{a,y,c}},{{b,y,c},{b,y+h,c},{b,y+h,d},{b,y,d}},{{a,y+h,c},{a,y+h,d},{b,y+h,d},{b,y+h,c}},{{a,y,d},{a,y,c},{b,y,c},{b,y,d}}};double[][] norms={{0,0,-1},{0,0,1},{-1,0,0},{1,0,0},{0,1,0},{0,-1,0}};GL11.glBegin(GL11.GL_QUADS);for(int i=0;i<6;i++){GL11.glNormal3d(norms[i][0],norms[i][1],norms[i][2]);double[][] p=faces[i];for(int j=0;j<4;j++){GL11.glTexCoord2d(j==1||j==2?U:u,j>=2?V:v);GL11.glVertex3d(p[j][0],p[j][1],p[j][2]);}}GL11.glEnd();}
}
